using System;
using System.Configuration;
using System.Data;
using System.Data.SqlClient;
using FormularioWeb.Security;

namespace FormularioWeb.Data
{
    public class PortalRepository
    {
        private readonly string cs=ConfigurationManager.ConnectionStrings["ConexionFormulario"].ConnectionString;
        public int Registrar(string cedula,string nombres,string apellidos,string correo,string telefono,string programa,int semestre,string password){using(var cn=new SqlConnection(cs)){cn.Open();using(var tx=cn.BeginTransaction(IsolationLevel.Serializable)){try{int id;using(var find=new SqlCommand("SELECT Id,Correo FROM dbo.Estudiantes WITH(UPDLOCK,HOLDLOCK) WHERE Cedula=@c",cn,tx)){find.Parameters.Add("@c",SqlDbType.VarChar,20).Value=cedula;using(var r=find.ExecuteReader()){if(r.Read()){id=r.GetInt32(0);if(!String.Equals(r.GetString(1),correo,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("La cédula ya existe con otro correo. Contacta a soporte para validar la cuenta.");}else id=0;}}if(id>0){using(var exists=new SqlCommand("SELECT COUNT(*) FROM dbo.CuentaEstudiante WHERE EstudianteId=@id",cn,tx)){exists.Parameters.Add("@id",SqlDbType.Int).Value=id;if((int)exists.ExecuteScalar()>0)throw new InvalidOperationException("Ya existe una cuenta para esta cédula. Inicia sesión.");}}else{using(var insert=new SqlCommand(@"INSERT dbo.Estudiantes(Cedula,CodigoRegistro,Nombres,Apellidos,Correo,Telefono,Programa,Semestre,Participacion,Jornada,TemasInteres,Comentarios,AceptaTratamiento,FechaRegistro) VALUES(@ced,@codigo,@nom,@ape,@correo,@tel,@prog,@sem,N'Estudiante',N'No aplica',NULL,NULL,1,SYSDATETIME());SELECT CAST(SCOPE_IDENTITY() AS int);",cn,tx)){insert.Parameters.Add("@ced",SqlDbType.VarChar,20).Value=cedula;insert.Parameters.Add("@codigo",SqlDbType.VarChar,30).Value="PORT-"+Guid.NewGuid().ToString("N").Substring(0,20);insert.Parameters.Add("@nom",SqlDbType.NVarChar,100).Value=nombres;insert.Parameters.Add("@ape",SqlDbType.NVarChar,100).Value=apellidos;insert.Parameters.Add("@correo",SqlDbType.NVarChar,150).Value=correo;insert.Parameters.Add("@tel",SqlDbType.VarChar,20).Value=telefono;insert.Parameters.Add("@prog",SqlDbType.NVarChar,100).Value=programa;insert.Parameters.Add("@sem",SqlDbType.Int).Value=semestre;id=(int)insert.ExecuteScalar();}}var salt=PasswordHasher.NuevaSal();var hash=PasswordHasher.Hash(password,salt);using(var save=new SqlCommand("INSERT dbo.CuentaEstudiante(EstudianteId,Salt,ClaveHash) VALUES(@id,@salt,@hash)",cn,tx)){save.Parameters.Add("@id",SqlDbType.Int).Value=id;save.Parameters.Add("@salt",SqlDbType.VarBinary,16).Value=salt;save.Parameters.Add("@hash",SqlDbType.VarBinary,32).Value=hash;save.ExecuteNonQuery();}tx.Commit();return id;}catch{tx.Rollback();throw;}}}}
        public int? IniciarSesion(string cedula,string password,out string nombre){nombre=null;using(var cn=new SqlConnection(cs))using(var cmd=new SqlCommand(@"SELECT e.Id,e.Nombres,e.Apellidos,c.Salt,c.ClaveHash FROM dbo.Estudiantes e JOIN dbo.CuentaEstudiante c ON c.EstudianteId=e.Id WHERE e.Cedula=@ced",cn)){cmd.Parameters.Add("@ced",SqlDbType.VarChar,20).Value=cedula;cn.Open();using(var r=cmd.ExecuteReader()){if(!r.Read())return null;var salt=(byte[])r[3];var hash=(byte[])r[4];if(!PasswordHasher.Verificar(password,salt,hash))return null;nombre=r.GetString(1)+" "+r.GetString(2);return r.GetInt32(0);}}}
        public DataTable Disponibles(int estudiante){var t=new DataTable();const string sql=@"SELECT a.ActividadId,a.Titulo,a.Tipo,a.FechaInicio,a.FechaFin,a.HoraInicio,a.HoraFin,a.Modalidad,a.Lugar,a.Cupo,COUNT(i.InscripcionId) Inscritos,a.Estado FROM dbo.ActividadAcademica a LEFT JOIN dbo.InscripcionActividad i ON i.ActividadId=a.ActividadId WHERE a.Estado IN(N'Próxima',N'Activa') AND (a.FechaInicio>CAST(GETDATE() AS date) OR (a.FechaInicio=CAST(GETDATE() AS date) AND a.HoraInicio>CAST(GETDATE() AS time))) AND NOT EXISTS(SELECT 1 FROM dbo.InscripcionActividad mine WHERE mine.ActividadId=a.ActividadId AND mine.EstudianteId=@e) GROUP BY a.ActividadId,a.Titulo,a.Tipo,a.FechaInicio,a.FechaFin,a.HoraInicio,a.HoraFin,a.Modalidad,a.Lugar,a.Cupo,a.Estado ORDER BY a.FechaInicio";using(var cn=new SqlConnection(cs))using(var cmd=new SqlCommand(sql,cn))using(var da=new SqlDataAdapter(cmd)){cmd.Parameters.Add("@e",SqlDbType.Int).Value=estudiante;da.Fill(t);}return t;}
        public DataTable MisInscripciones(int estudiante){var t=new DataTable();const string sql=@"SELECT a.ActividadId,a.Titulo,a.Tipo,a.FechaInicio,a.FechaFin,a.HoraInicio,a.HoraFin,a.Lugar,i.FechaInscripcion,CAST(CASE WHEN EXISTS(SELECT 1 FROM dbo.ResenaActividad r WHERE r.ActividadId=a.ActividadId AND r.EstudianteId=i.EstudianteId) THEN 1 ELSE 0 END AS bit) AS YaReseno FROM dbo.InscripcionActividad i JOIN dbo.ActividadAcademica a ON a.ActividadId=i.ActividadId WHERE i.EstudianteId=@e ORDER BY i.FechaInscripcion DESC";using(var cn=new SqlConnection(cs))using(var cmd=new SqlCommand(sql,cn))using(var da=new SqlDataAdapter(cmd)){cmd.Parameters.Add("@e",SqlDbType.Int).Value=estudiante;da.Fill(t);}return t;}
        public void Inscribir(int actividad,int estudiante){using(var cn=new SqlConnection(cs)){cn.Open();using(var tx=cn.BeginTransaction(IsolationLevel.Serializable)){try{using(var check=new SqlCommand("SELECT Cupo,Estado,FechaInicio,HoraInicio,(SELECT COUNT(*) FROM dbo.InscripcionActividad WITH(UPDLOCK,HOLDLOCK) WHERE ActividadId=@a) FROM dbo.ActividadAcademica WITH(UPDLOCK,HOLDLOCK) WHERE ActividadId=@a",cn,tx)){check.Parameters.Add("@a",SqlDbType.Int).Value=actividad;using(var r=check.ExecuteReader()){if(!r.Read())throw new InvalidOperationException("No se encontró la actividad.");var inicio=r.GetDateTime(2).Date+r.GetTimeSpan(3);if(r.GetString(1)=="Cancelada"||r.GetString(1)=="Finalizada"||inicio<=DateTime.Now)throw new InvalidOperationException("Esta actividad ya no está disponible para inscripciones.");if(r.GetInt32(0)<=r.GetInt32(4))throw new InvalidOperationException("La actividad ya no tiene cupos.");}}using(var cmd=new SqlCommand("INSERT dbo.InscripcionActividad(ActividadId,EstudianteId) VALUES(@a,@e)",cn,tx)){cmd.Parameters.Add("@a",SqlDbType.Int).Value=actividad;cmd.Parameters.Add("@e",SqlDbType.Int).Value=estudiante;cmd.ExecuteNonQuery();}tx.Commit();}catch{tx.Rollback();throw;}}}}
        public void GuardarResena(int actividad,int estudiante,int calificacion,string comentario){using(var cn=new SqlConnection(cs)){cn.Open();using(var tx=cn.BeginTransaction(IsolationLevel.Serializable)){try{using(var check=new SqlCommand(@"SELECT COUNT(*) FROM dbo.InscripcionActividad i WITH(UPDLOCK,HOLDLOCK) JOIN dbo.ActividadAcademica a ON a.ActividadId=i.ActividadId WHERE i.ActividadId=@a AND i.EstudianteId=@e AND DATEADD(SECOND,DATEDIFF(SECOND,CAST('00:00:00' AS time),a.HoraFin),CAST(a.FechaFin AS datetime2))<=SYSDATETIME()",cn,tx)){check.Parameters.Add("@a",SqlDbType.Int).Value=actividad;check.Parameters.Add("@e",SqlDbType.Int).Value=estudiante;if((int)check.ExecuteScalar()==0)throw new InvalidOperationException("Solo puedes calificar una actividad en la que estés inscrito y que ya haya finalizado.");}using(var cmd=new SqlCommand("INSERT dbo.ResenaActividad(ActividadId,EstudianteId,Calificacion,Comentario) VALUES(@a,@e,@c,@t)",cn,tx)){cmd.Parameters.Add("@a",SqlDbType.Int).Value=actividad;cmd.Parameters.Add("@e",SqlDbType.Int).Value=estudiante;cmd.Parameters.Add("@c",SqlDbType.TinyInt).Value=calificacion;cmd.Parameters.Add("@t",SqlDbType.NVarChar,1000).Value=String.IsNullOrWhiteSpace(comentario)?(object)DBNull.Value:comentario.Trim();cmd.ExecuteNonQuery();}tx.Commit();}catch{tx.Rollback();throw;}}}}
    }
}
